"""Exceptional remedies and HC: current constitutional and 2024 safeguards."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
CPC='https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm'
LAW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14836.htm'
MIL='https://portal.stf.jus.br/constituicao-supremo/artigo.asp?abrirArtigo=142&abrirBase=CF'
SV='https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n).lower()]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(637,'Ausência de efeito suspensivo do recurso extraordinário não autoriza, isoladamente, execução automática de toda condenação.', ['Integrar CPP283 e presunção de inocência.', 'Separar prisão cautelar fundamentada e regime específico do júri.'], 'A antiga previsão de baixar autos para execução não afasta as garantias atuais; júri exige leitura própria do Tema1068.', 'Réu condenado fora do júri interpõe recurso excepcional; isso, sozinho, não cria mandado de prisão.', 'Preventiva válida pode persistir por fundamento cautelar próprio, não como execução antecipada genérica.', ['RE sem efeito suspensivo basta para prender todo condenado? Não.', 'Prisão cautelar possui fundamento próprio? Sim.'], 'Efeito suspensivo','Efeito recursal distinto dos pressupostos da prisão.',[CF])
add(638,'Recursos extraordinário e especial seguem leis específicas, legislação processual civil e regimentos de STF e STJ.', ['Redação de2019 inclui expressamente recurso especial.', 'Verificar espécie, admissibilidade e regime pertinente.'], 'Não usar procedimentos históricos seguintes para substituir automaticamente o regime atual dos recursos excepcionais.', 'Questão constitucional é examinada na via extraordinária quando preenchidos requisitos.', 'Questão de lei federal pode exigir recurso especial, sem transformar STF em revisor de qualquer erro.', ['O dispositivo inclui recurso especial? Sim.', 'Regimento dispensa pressupostos legais? Não.'], 'Recursos excepcionais','Vias aos tribunais superiores com requisitos próprios.',[CPC,CF])
add(639,'Carta testemunhável protege processamento de recurso denegado ou obstado após admissão, quando não houver via própria adequada.', ['Instrumento de caráter residual.', 'Distinguir denegação e impedimento de seguimento.'], 'Não confundir com RESE contra denegação de apelação nem agravos próprios dos recursos excepcionais.', 'Recurso cabível tem seguimento bloqueado e não existe impugnação específica; examina-se carta.', 'Inadmissão de RE ou REsp exige identificar a hipótese do CPC, não recorrer sempre por carta.', ['Carta substitui toda impugnação específica? Não.', 'Pode enfrentar obstáculo posterior à admissão? Sim.'], 'Carta testemunhável','Instrumento residual de proteção do trânsito recursal.',[CPC])
add(640,'Carta é requerida ao escrivão ou secretário em quarenta e oito horas da decisão denegatória, com indicação das peças.', ['Selecionar documentos suficientes ao exame.', 'Distinguir requerimento e entrega do instrumento.'], 'Não confundir48 horas do pedido com cinco dias de entrega em hipótese de RESE.', 'Defesa indica decisão, recurso e peças essenciais ao pedir o instrumento no prazo.', 'Pedido sem peças necessárias pode comprometer compreensão; não basta apenas citar nome do recurso.', ['Prazo textual do requerimento é48 horas? Sim.', 'Peças devem ser indicadas? Sim.'], 'Instrumentação','Reunião dos elementos necessários à carta.')
add(641,'Serventia dá recibo e entrega a carta no prazo textual de cinco dias quando relacionada a recurso em sentido estrito.', ['Recibo documenta requerimento.', 'Previsão de sessenta dias para extraordinário é histórica.'], 'Não ensinar sessenta dias como prazo atual geral para impugnar inadmissão de RE: aplicar regime do CPC.', 'Pedido relativo a RESE recebe recibo e processamento pertinente em cinco dias.', 'RE inadmitido segue impugnação específica, não o prazo antigo de entrega da carta.', ['Cinco dias referem-se à entrega na hipótese de RESE? Sim.', 'Sessenta dias são prazo atual universal do RE? Não.'], 'Recibo da carta','Prova do requerimento e controle de entrega.',[CPC])
add(642,'Obstáculo da serventia à entrega da carta pode ser representado para assegurar o instrumento e apurar responsabilidade.', ['Texto prevê substituição e reclamação ao órgão superior.', 'Integrar apuração disciplinar ao devido processo.'], 'Não prometer sanção administrativa sumária automática: competência, defesa e regime funcional precisam ser respeitados.', 'Serventia se recusa a entregar; parte documenta fato e provoca autoridade competente.', 'Dificuldade justificada é apurada, sem presumir falta funcional pela simples demora.', ['A parte pode reagir à recusa da serventia? Sim.', 'Defesa disciplinar pode ser ignorada? Não.'], 'Proteção do processamento','Providências contra obstrução indevida do instrumento.',[CF])
add(643,'Carta relacionada a RESE observa processamento pertinente desse recurso; remissão histórica ao extraordinário exige integração atual.', ['Considerar artigos588 a592 na hipótese aplicável.', 'Regime excepcional atual decorre também do638.'], 'Não restaurar carta como sucedâneo universal do agravo em RE/REsp.', 'Instrumento de RESE segue exame e encaminhamento adequados.', 'Denegação de recurso excepcional exige primeiro identificar a decisão e o agravo próprio.', ['RESE orienta o processamento da carta correspondente? Sim.', 'Remissão antiga afasta CPC atual? Não.'], 'Rito do instrumento','Processamento conforme recurso e regime atual.',[CPC])
add(644,'Recebida a carta, tribunal pode mandar processar o recurso ou julgar seu mérito se o instrumento estiver suficientemente instruído.', ['Determinar processamento não equivale a prover mérito.', 'Julgamento direto depende da suficiência das peças.'], 'Admissão da carta não significa absolvição ou provimento automático do recurso original.', 'Faltam peças para mérito, mas obstáculo é indevido; tribunal ordena processamento.', 'Instrumento completo permite examinar desde logo questão recursal pertinente.', ['Pode haver julgamento direto com instrução suficiente? Sim.', 'Carta admitida garante provimento do recurso? Não.'], 'Suficiência do instrumento','Elementos que permitem exame direto do recurso.')
add(645,'No tribunal, carta segue procedimento compatível com o recurso denegado e seu regime atual.', ['A espécie recursal orienta tramitação.', 'Integrar competência e regimento.'], 'Carta não cria rito único indiferente ao recurso ou órgão competente.', 'Instrumento relativo a RESE é distribuído segundo regras aplicáveis.', 'Nome antigo de órgão não autoriza remessa a tribunal extinto.', ['Recurso denegado orienta procedimento? Sim.', 'Carta elimina regras de competência? Não.'], 'Correspondência procedimental','Tramitação vinculada à espécie recursal.')
add(646,'Carta testemunhável não possui efeito suspensivo por si.', ['Distinguir instrumento e efeito do recurso original.', 'Medida urgente depende de fundamento próprio.'], 'Não concluir que ausência de suspensão autoriza prisão sem os pressupostos atuais.', 'Carta questiona obstáculo recursal, mas não suspende automaticamente a decisão.', 'Tutela urgente pertinente exige pedido e exame próprios, não simples nome do instrumento.', ['Carta suspende automaticamente a decisão? Não.', 'Efeito do recurso original é questão distinta? Sim.'], 'Efeito da carta','Ausência de suspensão automática.')
add(647,'Habeas corpus tutela liberdade de locomoção diante de coação ilegal atual ou ameaçada.', ['Distinguir HC liberatório e preventivo.', 'Restrição disciplinar militar não impede todo controle de legalidade.'], 'STF distingue mérito da punição militar e seus pressupostos legais; não ensinar imunidade absoluta ao controle judicial nem revisão irrestrita do mérito.', 'Prisão sem justa causa pode justificar HC liberatório.', 'Punição militar exige distinguir exame da legalidade e reavaliação do mérito disciplinar.', ['Ameaça ilegal à locomoção pode justificar HC? Sim.', 'Exceção militar elimina qualquer controle de legalidade? Não.'], 'Liberdade de locomoção','Bem protegido pelo habeas corpus.',[CF,MIL])
add('647-A','Lei14.836/2024 permite HC de ofício, individual ou coletivo, dentro da competência judicial.', ['Pode surgir em qualquer processo judicial.', 'Pode ser concedido mesmo sem conhecimento da ação ou recurso.', 'Competência jurisdicional continua necessária.'], 'Não confundir concessão de ofício com competência universal de qualquer juiz.', 'Tribunal não conhece recurso, mas constata coação ilegal e examina HC de ofício em sua competência.', 'Violação comum a grupo pode fundamentar ordem coletiva, delimitados sujeitos e pressupostos.', ['Ordem pode ser coletiva? Sim.', 'Não conhecimento do recurso impede necessariamente HC de ofício? Não.'], 'HC de ofício','Tutela judicial da liberdade sem depender de pedido formal conhecido.',[LAW])
add(648,'Artigo enumera hipóteses de coação ilegal, como falta de justa causa, excesso de prazo e autoridade incompetente.', ['Também cessação do motivo, recusa ilegal de fiança, nulidade manifesta e extinção da punibilidade.', 'Relacionar fundamento e providência adequada.'], 'Excesso de prazo não deve ser calculado mecanicamente sem examinar regime, circunstâncias e responsabilidade pela demora.', 'Prisão continua depois de extinta punibilidade; examina-se cessação da coação.', 'Recusa de fiança só entra na hipótese se a lei a admitir no caso.', ['Falta de justa causa é hipótese expressa? Sim.', 'Toda recusa de fiança é ilegal? Não.'], 'Coação ilegal','Restrição ou ameaça incompatível com o ordenamento.')
add(649,'Juiz ou tribunal competente deve conceder imediatamente ordem cabível, qualquer que seja o agente da coação.', ['Urgência da proteção.', 'Competência precisa ser observada.'], 'Qualquer coator não significa qualquer juiz competente para qualquer autoridade.', 'Juízo competente identifica coação ilegal praticada por particular e determina proteção.', 'Autoridade sujeita a tribunal superior exige análise de competência própria.', ['Coator pode não ser autoridade pública? Sim.', 'Competência é dispensável? Não.'], 'Agente da coação','Quem produz a restrição ilegal, respeitada competência judicial.',[CF])
add(650,'Competência de habeas corpus deve ser lida pela Constituição e organização judiciária atuais.', ['Órgãos e referências constitucionais antigos não bastam.', 'Parágrafo sobre prisão por obrigações fazendárias exige controle constitucional.', 'SV25 afasta prisão civil do depositário infiel.'], 'Não restaurar competência histórica nem prisão administrativa genérica por dívida; separar exceção constitucional alimentar.', 'HC envolvendo autoridade com foro competente é encaminhado ao órgão constitucional adequado.', 'Dívida perante Fazenda não autoriza, por si, prisão administrativa fundada na redação antiga.', ['Referência constitucional antiga resolve toda competência atual? Não.', 'Dívida fazendária permite prisão administrativa genérica? Não.'], 'Competência constitucional','Distribuição atual do controle judicial da coação.',[CF,SV])
add(651,'Concessão de HC não impede necessariamente continuação do processo, se o fundamento for compatível com seu prosseguimento.', ['Liberdade e encerramento da ação são efeitos distintos.', 'Motivo da ordem delimita consequências.'], 'Não tratar todo HC liberatório como absolvição ou trancamento.', 'Preventiva é revogada por falta de fundamento, mas ação válida pode continuar.', 'Reconhecimento de causa que impede a própria persecução pode exigir resultado diverso.', ['Soltura por HC sempre encerra ação? Não.', 'Fundamento da concessão importa? Sim.'], 'Efeito delimitado','Consequência ajustada à ilegalidade reconhecida.')
add(652,'Quando HC reconhece nulidade, processo deve ser renovado nos limites compatíveis com a decisão e o regime atual.', ['Identificar atos atingidos e dependentes.', 'Não ignorar outras causas que impeçam nova persecução.'], 'Nulidade não autoriza repetição ilimitada de ação já vedada por fundamento autônomo.', 'Citação inválida exige renovar atos atingidos com defesa regular.', 'Extinção da punibilidade não vira mera oportunidade de refazer instrução.', ['Nulidade pode exigir renovação de atos? Sim.', 'Renovação afasta extinção da punibilidade? Não.'], 'Renovação processual','Reconstituição dos atos afetados pela nulidade.')
add(653,'Má-fé ou abuso de poder do responsável pela coação pode gerar custas e envio de peças ao MP para responsabilidade.', ['Reconhecimento exige fundamento.', 'Remessa de peças não equivale a condenação criminal.'], 'Procedência do HC não prova automaticamente má-fé de todo coator.', 'Decisão identifica abuso e remete elementos para apuração adequada.', 'Erro reconhecido sem prova de má-fé não dispensa exame dos pressupostos de responsabilidade.', ['Todo HC procedente prova má-fé? Não.', 'Peças podem ser encaminhadas ao MP? Sim.'], 'Responsabilidade do coator','Apuração das consequências do abuso comprovado.')
add(654,'Qualquer pessoa pode impetrar HC em favor próprio ou alheio; Ministério Público também pode fazê-lo.', ['Identificar paciente, coator e constrangimento ou ameaça.', 'Petição tem assinatura ou assinatura a rogo e elementos previstos.', 'Ofício integra também647-A.'], 'Não exigir advogado como requisito universal de impetração nem confundir impetrante e paciente.', 'Familiar relata prisão ilegal de terceiro e identifica agente e circunstâncias.', 'Paciente pode ser a própria pessoa que assina o pedido.', ['Impetrante precisa sempre ser advogado? Não.', 'MP pode impetrar HC? Sim.'], 'Paciente','Pessoa cuja liberdade é protegida no pedido.',[LAW])
add(655,'Dispositivo histórico responsabiliza quem embaraça tramitação, informações, apresentação ou soltura em HC.', ['Referência monetária a mil-réis é histórica.', 'Sanção atual exige base legal e procedimento próprios.'], 'Não converter quantias antigas em multa atual automática ou gerar exercício numérico com moeda extinta.', 'Obstrução injustificada de soltura é comunicada para providências legais cabíveis.', 'Falha material deve ser esclarecida antes de atribuir responsabilidade pessoal.', ['Mil-réis são parâmetro atual automático de multa? Não.', 'Obstrução indevida exige providência adequada? Sim.'], 'Obstrução da ordem','Conduta que impede efetividade da proteção judicial.',[CF])
add(656,'Quando necessário, juiz pode determinar apresentação imediata do paciente preso para examinar coação.', ['Necessidade deve ser avaliada.', 'Recusa do detentor tem consequências previstas, integradas às garantias atuais.'], 'Não equiparar impossibilidade justificada a desobediência nem decretar prisão punitiva automática sem requisitos.', 'Apresentação permite verificar condições e ouvir pessoa detida.', 'Doença grave documentada exige examinar exceção e providência alternativa do657.', ['Apresentação é determinada quando necessária? Sim.', 'Toda impossibilidade equivale automaticamente a crime? Não.'], 'Apresentação do paciente','Providência para exame direto da situação de custódia.')
add(657,'Doença grave, falta de custódia e ausência de ordem de apresentação são hipóteses textuais relacionadas à apresentação do preso.', ['Doença pode exigir visita judicial.', 'Justificativa não torna prisão automaticamente legal.'], 'Separar impossibilidade de transportar paciente e mérito da coação.', 'Preso gravemente enfermo não pode ser transportado; juiz examina situação onde ele se encontra.', 'Pessoa já não está sob poder do detentor exige esclarecer localização e eventual coação restante.', ['Doença grave pode impedir transporte? Sim.', 'Isso elimina exame da ilegalidade? Não.'], 'Exceção de apresentação','Ajuste da providência à situação concreta.')
add(658,'Detentor deve declarar à ordem de quem o paciente está preso.', ['Identificar título e responsável.', 'Subsidiar competência e legalidade.'], 'Nome do responsável não substitui demonstração de fundamento válido da prisão.', 'Unidade informa que custódia decorre de mandado de determinado juízo.', 'Ausência de ordem identificável exige apuração da legalidade, não mero silêncio.', ['Detentor informa a autoridade da ordem? Sim.', 'Informação dispensa controle do título? Não.'], 'Identificação da custódia','Esclarecimento da origem e responsabilidade pela restrição.')
add(659,'Se realmente cessou a violência ou coação ilegal, pedido pode ser julgado prejudicado.', ['Verificar desaparecimento efetivo da restrição.', 'Não basta mudança formal de documento.'], 'Novo título que mantém a mesma ilegalidade exige exame pertinente; não presumir perda do objeto só por substituição nominal.', 'Pessoa é liberada e ameaça combatida deixa de existir.', 'Nova ordem mantém vício alegado; situação concreta precisa ser examinada.', ['Cessação efetiva pode prejudicar pedido? Sim.', 'Troca nominal do título prova sempre cessação? Não.'], 'Perda do objeto','Desaparecimento real da coação discutida.')
add(660,'Após diligências e oitiva pertinente, decisão fundamentada observa prazo textual de vinte e quatro horas, sem impedir tutela imediata.', ['Documentos que evidenciam ilegalidade permitem cessação imediata.', 'Soltura ressalva outro título válido; fiança pode ser arbitrada se cabível.', 'HC preventivo pode resultar em salvo-conduto.', 'Comunicação deve ser célere e autenticada.'], 'Não esperar24 horas diante de ilegalidade já comprovada nem restaurar medida provisória histórica; salvo-conduto não é imunidade para novos crimes.', 'Documentos demonstram prisão ilegal; juiz ordena cessação de imediato.', 'Outro mandado válido exige análise própria antes de liberdade física; ameaça ilegal pode pedir salvo-conduto.', ['É obrigatório esperar24 horas com ilegalidade evidente? Não.', 'HC preventivo pode gerar salvo-conduto? Sim.'], 'Salvo-conduto','Proteção contra ameaça ilegal delimitada pela decisão.')
add(661,'HC originário de tribunal segue recebimento e encaminhamento pelo órgão competente, integrado à organização e regimento atuais.', ['Distinguir competência originária e recursal.', 'Preservar prioridade da tutela de liberdade.'], 'Não encaminhar pedido a qualquer tribunal apenas porque se chama HC.', 'Secretaria encaminha pedido originário ao órgão definido pelas normas atuais.', 'Caso de competência de primeiro grau exige exame da via apropriada.', ['Competência originária precisa existir? Sim.', 'Nome do pedido permite escolher qualquer tribunal? Não.'], 'HC originário','Pedido submetido diretamente ao órgão competente.',[CF])
add(662,'Verificados requisitos, tribunal pode pedir informações necessárias e suprir omissões pertinentes ao julgamento.', ['Informações são instrumentais.', 'Não transformar formalidade em demora injustificada diante da urgência.'], 'A falta de um dado pode exigir esclarecimento, sem negar automaticamente proteção evidenciada por outros elementos.', 'Relator solicita ordem prisional para esclarecer fundamento da coação.', 'Documentação suficiente demonstra ilegalidade e permite examinar medida urgente sem espera burocrática.', ['Informações servem ao exame do pedido? Sim.', 'Pedido de informações justifica qualquer demora? Não.'], 'Instrução do HC','Elementos necessários à decisão sobre liberdade.')
add(663,'Texto prevê submissão à deliberação do tribunal quando não há indeferimento liminar, com integração às normas atuais.', ['Considerar atribuições de relator e colegiado.', 'Distinguir informações e admissibilidade.'], 'Não extrair do texto antigo proibição universal de decisões previstas em regimento válido ou eliminação de impugnação cabível.', 'Pedido apto segue exame pelo órgão competente conforme tramitação aplicável.', 'Indeferimento exige fundamento e exame das vias pertinentes, não fechamento automático de toda revisão.', ['Deliberação segue competência e regras atuais? Sim.', 'Indeferimento dispensa motivação? Não.'], 'Deliberação do HC','Exame decisório conforme lei e organização atual.',[CF])
add(664,'HC tem julgamento prioritário; empate deve seguir regra atual favorável ao imputado do615§1, alterado em2024.', ['Primeira sessão, com eventual adiamento para a seguinte no texto.', 'Não restaurar voto presidencial desfavorável de desempate.', 'Nova regra alcança matéria penal e processual penal colegiada.'], 'Ler apenas o parágrafo antigo produz resposta errada sobre desempate após Lei14.836/2024.', 'Dois votos concedem e dois negam HC; prevalece resultado favorável ao imputado.', 'Composição incompleta não elimina a regra nas hipóteses legais.', ['Empate permite negar HC só por voto presidencial antigo? Não.', 'Regra de2024 favorece imediatamente imputado? Sim.'], 'Empate favorável','Resultado protetivo imposto pelo regime atual.',[LAW])
add(665,'Ordem concedida deve chegar prontamente ao detentor ou coator por comunicação oficial adequada.', ['Texto menciona secretário, assinatura presidencial e telegrama.', 'Integrar meios oficiais atuais e autenticação.'], 'Telegrama histórico não torna inválida toda comunicação eletrônica oficial nem permite mensagem sem autenticidade.', 'Secretaria transmite ordem judicial autenticada para cumprimento.', 'Captura de tela não verificada exige confirmação oficial, sem criar demora arbitrária à soltura.', ['Comunicação precisa ser oficial e autêntica? Sim.', 'Somente telegrama é meio possível hoje? Não.'], 'Comunicação da ordem','Transmissão confiável para efetivar proteção.')
add(666,'Regimentos complementam processo e julgamento de HC originário nos tribunais, respeitadas normas superiores.', ['Organizar distribuição, sessão e atos internos.', 'Não alterar competência constitucional por conveniência.'], 'Regimento não pode suprimir garantia legal de proteção da liberdade.', 'Norma interna identifica órgão julgador competente.', 'Regra interna incompatível com Constituição não prevalece só por ser específica.', ['Regimento complementa procedimento? Sim.', 'Pode afastar Constituição? Não.'], 'Complemento regimental','Organização do tribunal subordinada ao ordenamento.',[CF])
add(667,'HC perante STF, originário ou recursal, segue competência constitucional e regimento, com aplicação compatível das regras antecedentes.', ['Distinguir pedido originário e recurso cabível.', 'Não presumir acesso direto universal ao Supremo.'], 'Todo HC não é automaticamente matéria originária do STF; respeitar autoridade coatora e via constitucional.', 'Caso constitucionalmente atribuído ao STF segue seu processamento próprio.', 'Pedido fora da competência não ganha admissibilidade só por alegar urgência, sem prejuízo de tutela cabível no órgão adequado.', ['STF tem competência universal para todo HC? Não.', 'Regras antecedentes aplicam-se quando compatíveis? Sim.'], 'HC no STF','Tutela constitucional conforme competência e via adequada.',[CF])
assert len(rows)==32
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'HC and exceptional remedies units reviewed')
